from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class SpeechRecognitionResult:
    text: str
    is_final: bool
    language: Optional[str] = None
    offset_milliseconds: Optional[int] = None
    duration_milliseconds: Optional[int] = None
    sentiment_score: Optional[float] = None
    sentiment_magnitude: Optional[float] = None
    speaker_id: Optional[str] = None
    raw_response: Optional[Dict[str, Any]] = field(default_factory=dict)

def normalize_azure_speech_result(azure_event, is_final: bool) -> SpeechRecognitionResult:
    return SpeechRecognitionResult(
        text=azure_event.result.text,
        is_final=is_final,
        raw_response={
            "reason": str(azure_event.result.reason),
            "text": azure_event.result.text,
            "json": azure_event.result.json
        }
    )

import azure.cognitiveservices.speech as speechsdk

def get_speech_config(api_key: str, region: str, language_code: str = "en-US", enable_punctuation: bool = False):
    speech_config = speechsdk.SpeechConfig(subscription=api_key, region=region)
    speech_config.speech_recognition_language = language_code
    if enable_punctuation:
        speech_config.set_property(speechsdk.PropertyId.SpeechServiceResponse_PostProcessingOption, "TrueText")
    return speech_config

def get_audio_config_from_stream(stream):
    return speechsdk.audio.AudioConfig(stream=stream)

def get_push_audio_input_stream(sample_rate_hz: int, bits_per_sample: int = 16, channels: int = 1):
    return speechsdk.audio.PushAudioInputStream(speechsdk.audio.AudioStreamFormat(
        samples_per_second=sample_rate_hz, bits_per_sample=bits_per_sample, channels=channels))

def get_speech_recognizer(speech_config, audio_config):
    return speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

from typing import Generator, Dict, Any
from speech_models import SpeechRecognitionResult

def partial_results_handler(event_stream: Generator[SpeechRecognitionResult, None, None]):
    for result in event_stream:
        if result.is_final:
            print(f"Final: {result.text}")
        else:
            print(f"Partial: {result.text}")

def collect_partial_results(event_stream: Generator[SpeechRecognitionResult, None, None]) -> Dict[str, Any]:
    final_transcript_parts = []
    partial_transcript = ""
    for result in event_stream:
        if result.is_final:
            if partial_transcript:
                # If there was a partial before a final, store it as a completed part
                final_transcript_parts.append(partial_transcript.strip())
            final_transcript_parts.append(result.text.strip())
            partial_transcript = ""  # Reset partial after a final result
        else:
            partial_transcript = result.text

    # Add any remaining partial as a final part if the stream ends without a final event
    if partial_transcript:
        final_transcript_parts.append(partial_transcript.strip())

    return {"full_transcript": " ".join(final_transcript_parts).strip()}

from typing import Generator, Dict, Any
from google.cloud import translate_v2 as translate

from speech_models import SpeechRecognitionResult

def live_caption_translate(event_stream: Generator[SpeechRecognitionResult, None, None], target_language: str = "es") -> Generator[Dict[str, Any], None, None]:
    translate_client = translate.Client()

    for result in event_stream:
        if result.is_final and result.text:
            translation = translate_client.translate(result.text, target_language=target_language)
            yield {
                "original_text": result.text,
                "translated_text": translation['translatedText'],
                "target_language": target_language,
                "detected_source_language": translation['detectedSourceLanguage']
            }
